//! `RoomState`: everything persisted about one room, and the [`Op`]s that change it.
//!
//! The reducer ([`RoomState::apply`]) is pure and deterministic. Anything non-deterministic
//! (time, tokens, ids) is generated by the caller and carried inside the [`Op`], so replaying the
//! journal reproduces the live state exactly. Connections are *not* part of this state.

use std::collections::BTreeMap;

use poker_engine::blinds::{Blinds, BlindsMode, CashGame, Tournament};
use poker_engine::{Chips, Event, GameState, MAX_CHIPS, PlayerAction, PlayerId, PokerError};
use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::config::Timings;
use crate::protocol::{
    ErrorCode, Role, RoomConfig, ServerMessage, WireAllocation, error_from_engine,
};

/// A refusal, ready to become an `ERROR` message.
#[derive(Clone, Debug, PartialEq)]
pub struct RoomError {
    /// Machine-readable code.
    pub code: ErrorCode,
    /// Human-readable text.
    pub message: String,
    /// Extra numbers for the UI.
    pub details: Option<Value>,
}

impl RoomError {
    /// A refusal with just a code and text.
    #[must_use]
    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
        RoomError {
            code,
            message: message.into(),
            details: None,
        }
    }

    /// The wire form.
    #[must_use]
    pub fn to_message(&self) -> ServerMessage {
        ServerMessage::Error {
            code: self.code,
            message: self.message.clone(),
            details: self.details.clone(),
        }
    }
}

impl From<PokerError> for RoomError {
    fn from(error: PokerError) -> Self {
        match error_from_engine(&error) {
            ServerMessage::Error {
                code,
                message,
                details,
            } => RoomError {
                code,
                message,
                details,
            },
            _ => RoomError::new(ErrorCode::InternalError, error.to_string()),
        }
    }
}

/// One person in the room (seated player, host or spectator).
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Player {
    /// Stable id (`p_N` for players, `s_N` for spectators).
    pub id: String,
    /// Display name.
    pub name: String,
    /// Host, player or spectator.
    pub role: Role,
    /// Seat number, absent for spectators.
    pub seat: Option<u8>,
    /// SHA-256 of the session token (the token itself is never stored).
    pub token_hash: String,
    /// Value the next `GAME_ACTION` must carry.
    pub next_action_seq: u64,
    /// Since when the player has been sitting out, for the presence check.
    pub sat_out_since_ms: Option<u64>,
    /// Hands dealt while sitting out.
    pub hands_sat_out: u32,
    /// Since when the player has had no chips between hands.
    pub busted_since_ms: Option<u64>,
}

/// A top-up waiting for the host or for the end of the hand.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PendingRebuy {
    /// Player topping up.
    pub player_id: String,
    /// Chips to add.
    pub amount: u64,
    /// The host has approved it; it applies between hands.
    pub approved: bool,
}

/// A running "is this player still here?" check.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Presence {
    /// Player being checked.
    pub subject: String,
    /// Absolute time the check ends.
    pub deadline_ms: u64,
    /// Votes so far: voter id to "still playing".
    pub votes: BTreeMap<String, bool>,
}

/// Host-only operations.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(
    tag = "kind",
    rename_all = "SCREAMING_SNAKE_CASE",
    rename_all_fields = "camelCase"
)]
pub enum HostCommand {
    /// Deal the next hand.
    StartHand,
    /// End the all-in run-out.
    BeginShowdown,
    /// Choose winners.
    ResolveShowdown {
        /// One entry per pot.
        allocations: Vec<WireAllocation>,
    },
    /// Take back the last action.
    Undo,
    /// Freeze the game.
    Pause {
        /// Optional text.
        reason: Option<String>,
    },
    /// Unfreeze the game.
    ResumeGame,
    /// Approve a top-up.
    ApproveRebuy {
        /// Player topping up.
        player_id: String,
        /// Chips to add.
        amount: u64,
    },
    /// Remove a player.
    Kick {
        /// Player to remove.
        player_id: String,
    },
    /// Change settings between hands.
    Configure {
        /// New settings.
        config: RoomConfig,
    },
    /// Close the room.
    EndGame,
}

/// Every change to a room. Journaled before it is applied for real.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(
    tag = "kind",
    rename_all = "SCREAMING_SNAKE_CASE",
    rename_all_fields = "camelCase"
)]
pub enum Op {
    /// Someone joins as player or spectator.
    Join {
        /// Id chosen by the server.
        player_id: String,
        /// Display name.
        name: String,
        /// Watch only.
        spectator: bool,
        /// Preferred seat.
        seat: Option<u8>,
        /// Hash of the session token handed to the client.
        token_hash: String,
        /// Server time.
        at_ms: u64,
    },
    /// A player acts.
    Act {
        /// Acting player.
        player_id: String,
        /// Counter the client sent.
        action_seq: u64,
        /// The action.
        action: PlayerAction,
        /// Server time.
        at_ms: u64,
    },
    /// The host does something.
    Host {
        /// Must be the host.
        by: String,
        /// What.
        command: HostCommand,
        /// Server time.
        at_ms: u64,
    },
    /// The turn deadline passed.
    Timeout {
        /// Server time.
        at_ms: u64,
    },
    /// The player on turn has been disconnected for the whole grace period: act for them
    /// (check if free, else fold), exactly like a turn timeout.
    DisconnectTimeout {
        /// The player on turn.
        player_id: String,
        /// Server time.
        at_ms: u64,
    },
    /// A player skips or rejoins from the next hand.
    SetSittingOut {
        /// Player.
        player_id: String,
        /// New state.
        sitting_out: bool,
        /// Server time.
        at_ms: u64,
    },
    /// A player folds and sits out.
    LeaveTable {
        /// Player.
        player_id: String,
        /// Server time.
        at_ms: u64,
    },
    /// A player asks for a top-up.
    RequestRebuy {
        /// Player.
        player_id: String,
        /// Chips wanted.
        amount: u64,
        /// Server time.
        at_ms: u64,
    },
    /// A vote in a presence check.
    PresenceVote {
        /// Voter.
        voter: String,
        /// Player the check is about.
        subject: String,
        /// "Yes, still playing."
        still_playing: bool,
        /// Server time.
        at_ms: u64,
    },
    /// The subject says they are still here.
    PresenceAck {
        /// Player.
        player_id: String,
        /// Server time.
        at_ms: u64,
    },
    /// Time passed: expire presence checks, start new ones.
    Tick {
        /// Server time.
        at_ms: u64,
    },
}

/// A message for one person or for everybody in the room.
#[derive(Clone, Debug, PartialEq)]
pub enum Broadcast {
    /// Everyone connected.
    All(ServerMessage),
    /// One player (all of their connections).
    To(String, ServerMessage),
}

/// What an accepted [`Op`] produced.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Outcome {
    /// Messages to send besides the `STATE_UPDATE`.
    pub broadcasts: Vec<Broadcast>,
    /// The op was a repeat of an applied action: acknowledge only.
    pub duplicate: bool,
    /// Engine events of this op, in order (for bookkeeping and the ticker).
    pub engine_events: Vec<Event>,
    /// State changed (bump `stateVersion`, send `STATE_UPDATE`, journal the op).
    pub changed: bool,
}

/// All persisted room state.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RoomState {
    /// Room code.
    pub code: String,
    /// Current settings.
    pub config: RoomConfig,
    /// The poker engine state (including undo history).
    pub game: GameState,
    /// Everyone in the room, by id.
    pub players: BTreeMap<String, Player>,
    /// The host's player id.
    pub host_id: String,
    /// SHA-256 of the host token.
    pub host_token_hash: String,
    /// Counter clients use to detect missed updates.
    pub state_version: u64,
    /// Next number for generated ids.
    pub next_player_no: u32,
    /// Absolute time the acting player runs out of time.
    pub turn_deadline_ms: Option<u64>,
    /// Time left on the turn clock while paused.
    pub paused_remaining_ms: Option<u64>,
    /// When the first hand of a tournament started.
    pub tournament_started_ms: Option<u64>,
    /// Top-ups waiting to be applied.
    pub pending_rebuys: Vec<PendingRebuy>,
    /// Players to remove once their hand is over.
    pub pending_removals: Vec<String>,
    /// Chips that left the table with removed players (credits to settle).
    pub ledger: BTreeMap<String, u64>,
    /// Running presence check.
    pub presence: Option<Presence>,
    /// Time of the last accepted op.
    pub last_activity_ms: u64,
    /// The host closed the room.
    pub ended: bool,
}

/// First-level blinds scaled up for tournaments: numerator over 2 (1x, 1.5x, 2x, 3x, ...).
const LADDER_HALVES: [u64; 10] = [2, 3, 4, 6, 8, 12, 16, 24, 32, 48];

/// Turns client settings into engine blinds.
///
/// # Errors
/// `INVALID_AMOUNT` when the numbers cannot be played.
pub fn blinds_mode(config: &RoomConfig) -> Result<BlindsMode, RoomError> {
    let invalid = || RoomError::new(ErrorCode::InvalidAmount, "invalid room settings");
    if config.starting_chips == 0 || config.starting_chips > MAX_CHIPS || config.small_blind == 0 {
        return Err(invalid());
    }
    let level = |halves: u64| -> Result<Blinds, RoomError> {
        let scale = |value: u64| value.saturating_mul(halves).div_ceil(2);
        Ok(Blinds {
            small_blind: Chips::new(scale(config.small_blind)).map_err(|_| invalid())?,
            big_blind: Chips::new(scale(config.big_blind)).map_err(|_| invalid())?,
            ante: Chips::new(scale(config.ante)).map_err(|_| invalid())?,
        })
    };
    let mode = if config.is_tournament {
        let levels = LADDER_HALVES
            .iter()
            .map(|h| level(*h))
            .collect::<Result<Vec<_>, _>>()?;
        let level_ms = u64::from(config.blind_level_minutes.max(1)) * 60_000;
        BlindsMode::Tournament(Tournament { levels, level_ms })
    } else {
        BlindsMode::Cash(CashGame { blinds: level(2)? })
    };
    poker_engine::blinds::BlindsStrategy::validate(&mode)?;
    Ok(mode)
}

/// Trims and checks a display name: 1 to 20 characters of `[A-Za-z0-9 _-]`.
///
/// # Errors
/// `NAME_INVALID`.
pub fn validate_name(name: &str) -> Result<String, RoomError> {
    let trimmed = name.trim();
    let ok = !trimmed.is_empty()
        && trimmed.chars().count() <= 20
        && trimmed
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, ' ' | '_' | '-'));
    if ok {
        Ok(trimmed.to_owned())
    } else {
        Err(RoomError::new(
            ErrorCode::NameInvalid,
            "name must be 1 to 20 letters, digits, space, _ or -",
        ))
    }
}

pub(super) fn engine_id(id: &str) -> PlayerId {
    PlayerId::new(id)
}

impl RoomState {
    /// A new room with the host seated at seat 0.
    ///
    /// # Errors
    /// `NAME_INVALID` or `INVALID_AMOUNT`.
    pub fn new(
        code: String,
        config: RoomConfig,
        host_name: &str,
        host_token_hash: String,
        host_session_hash: String,
        at_ms: u64,
    ) -> Result<Self, RoomError> {
        let name = validate_name(host_name)?;
        let mode = blinds_mode(&config)?;
        let game = GameState::new(mode)?;
        let host_id = "p_1".to_owned();
        let mut state = RoomState {
            code,
            config,
            game,
            players: BTreeMap::new(),
            host_id: host_id.clone(),
            host_token_hash,
            state_version: 1,
            next_player_no: 2,
            turn_deadline_ms: None,
            paused_remaining_ms: None,
            tournament_started_ms: None,
            pending_rebuys: Vec::new(),
            pending_removals: Vec::new(),
            ledger: BTreeMap::new(),
            presence: None,
            last_activity_ms: at_ms,
            ended: false,
        };
        state.seat_player(&host_id, &name, Role::Host, Some(0), host_session_hash)?;
        Ok(state)
    }

    /// The id the next joiner would get. Does not reserve it: `Op::Join` advances the counter,
    /// so replaying the journal ends with the same counter.
    #[must_use]
    pub fn peek_id(&self, spectator: bool) -> String {
        format!(
            "{}_{}",
            if spectator { "s" } else { "p" },
            self.next_player_no
        )
    }

    /// Moves the id counter past `id` (called when a join is applied).
    pub(super) fn reserve_id(&mut self, id: &str) {
        let number = id.split_once('_').and_then(|(_, n)| n.parse::<u32>().ok());
        if let Some(number) = number {
            self.next_player_no = self.next_player_no.max(number.saturating_add(1));
        }
    }

    /// Whether this id belongs to a seated participant (host or player).
    #[must_use]
    pub fn is_seated(&self, id: &str) -> bool {
        self.players.get(id).is_some_and(|p| p.seat.is_some())
    }

    /// Does this session token belong to `id`?
    #[must_use]
    pub fn token_matches(&self, id: &str, token: &str) -> bool {
        self.players
            .get(id)
            .is_some_and(|p| crate::util::token::matches(token, &p.token_hash))
    }

    /// Does this host token belong to the room's host?
    #[must_use]
    pub fn host_token_matches(&self, token: &str) -> bool {
        crate::util::token::matches(token, &self.host_token_hash)
    }

    /// The player id for a session token, if any.
    #[must_use]
    pub fn player_for_token(&self, token: &str) -> Option<&Player> {
        self.players
            .values()
            .find(|p| crate::util::token::matches(token, &p.token_hash))
    }

    /// Earliest time something needs attention without any message arriving.
    #[must_use]
    pub fn next_wakeup_ms(&self, timings: &Timings) -> Option<u64> {
        let presence = self.presence.as_ref().map(|p| p.deadline_ms);
        let away = if self.presence.is_none() {
            self.players
                .values()
                .filter(|p| p.seat.is_some() && p.id != self.host_id)
                .filter_map(|p| p.sat_out_since_ms)
                .map(|since| since.saturating_add(timings.away_after_ms))
                .min()
        } else {
            None
        };
        [self.turn_deadline_ms, presence, away]
            .into_iter()
            .flatten()
            .min()
    }

    /// Applies an op. On `Err` the state may be partially changed: callers apply to a clone and
    /// swap it in only on `Ok`.
    ///
    /// # Errors
    /// A [`RoomError`] to send to whoever caused the op.
    pub fn apply(&mut self, op: Op, timings: &Timings) -> Result<Outcome, RoomError> {
        let at_ms = op.at_ms();
        let mut outcome = Outcome::default();
        self.dispatch(op, timings, &mut outcome)?;
        if outcome.changed {
            self.state_version = self.state_version.saturating_add(1);
            self.last_activity_ms = at_ms;
        }
        Ok(outcome)
    }
}

impl Op {
    /// The server time the op carries.
    #[must_use]
    pub fn at_ms(&self) -> u64 {
        match self {
            Op::Join { at_ms, .. }
            | Op::Act { at_ms, .. }
            | Op::Host { at_ms, .. }
            | Op::Timeout { at_ms }
            | Op::DisconnectTimeout { at_ms, .. }
            | Op::SetSittingOut { at_ms, .. }
            | Op::LeaveTable { at_ms, .. }
            | Op::RequestRebuy { at_ms, .. }
            | Op::PresenceVote { at_ms, .. }
            | Op::PresenceAck { at_ms, .. }
            | Op::Tick { at_ms } => *at_ms,
        }
    }
}
